# yaml-language-server: $schema=../../../packages/core/schema/scenario.schema.json
# Buyer side: discover a coffee, request a quote (the roaster's console shows a web notification, captured and
# overlaid), receive the roaster's proposal, download the PDF (a real PDF, rasterised into a document card).
#
# The `open-console` setup hook loads the supplier console in a background tab: it polls for quote requests and shows
# a web notification (Notification API) when ours arrives — the runner captures it (title, body, icon).
#
# "A few hours later": the setup arms an automatic proposal for the NEXT quote request
# (POST /api/quotes/auto-proposal), stamped 4 h 18 min after the request. The shop loads
# notifications on page load only, so nothing shows until the `proposal` scene reopens the
# shop: the bell then rings with the new proposal — deterministic, no waiting, no polling.
version: 1
video: quote
title: {kicker: For cafés, text: Request a quote in a minute}
outro: {tagline: "From request to proposal, in one place."}

setup:
  - name: reset
    http: {method: POST, url: "{{shop}}/api/reset"}
  - name: prepare-proposal
    http:
      method: POST
      url: "{{shop}}/api/quotes/auto-proposal"
      json: {after_minutes: 258, note: "Roasted on Monday, delivered within your window."}
      rollback: {method: DELETE, url: "{{shop}}/api/quotes/auto-proposal"}
  - name: open-console
    js: {page: console, code: "return location.href"}

teardown:
  - name: reset
    http: {method: POST, url: "{{shop}}/api/reset"}

scenes:
  - id: discover
    caption: {kicker: Discover, text: "Award-winning lots and fresh arrivals, roasted to order."}
    page: shop
    open: /
    steps:
      - hover: {text: "Finca Lirandel — Geisha", ms: 700}
      - scroll: {to: {text: Fresh arrivals}, offset: -100, duration: 1.6}
      - click: Selowa Ridge
      - wait_for: {target: {role: button, name: Request a quote}}
      - hold: 1.2

  # A full-screen chapter card (takes no capture time): the theme's card component (studio/card-title) with slots.
  - card: {slots: {kicker: Step two, title: Ask the roaster for a quote}}
    id: chapter-request

  - id: request
    caption: {kicker: Request a quote, text: "Choose the quantity, the bag size and the grind."}
    steps:
      - click: {role: button, name: Request a quote}
      - click: {aria: Increase, in: dialog}
      - click: {aria: Increase, in: dialog}
      - select: {field: Bag size, option: 5 kg}
      - select: {field: Grind, option: Whole bean}

  # Same page, same dialog: a second scene keeps each one short (the reference look: 4–25 s per scene).
  - id: delivery
    caption: {kicker: Delivery, text: "Pick your delivery window and leave a note for the roaster."}
    steps:
      - click: {label: Delivery window}
      - click: {aria: Next month}
      - click: {aria: "10 January 2027"}
      - click: {aria: "24 January 2027"}
      - type: {into: {label: Message}, text: "Light roast for filter, please. Deliveries before 9 am.", cps: 18}
      - click: {text: Send request, in: dialog}
      - wait_for: {text: Quote request sent}
      # The roaster's console (background tab) shows a web notification: overlaid when it showed.
      - hold: 3.2
        caption: {kicker: Instantly, text: "The roaster is notified the moment the request is sent."}
        overlay:
          component: studio/notification
          slots: {notification: quote-request, app: Northfield console}
          params: {style: macos}
          duration: 3

  - interstitial: {text: A few hours later, duration: 2.6}

  - id: proposal
    caption: {kicker: Proposal, text: "The roaster's proposal arrives as a notification, with a PDF ready to share."}
    open: /
    steps:
      - wait: 0.8
      - click: {aria: Notifications}
      - click: {text: New proposal from Northfield Roasters}
      - wait_for: {text: "€720.00"}
        mark: proposal
        # A callout on the proposal total, anchored to the element measured at the end of the step.
        overlay:
          component: studio/overlay-callout
          slots: {text: "Total incl. VAT, ready to accept"}
          duration: 2.5
          target: {testid: proposal-total}
      - hover: {text: Accept proposal, ms: 600}
        hold: 1.5
      # A real PDF opens in a new tab: captured with the session and rasterised (pdf.js) for the document card.
      - download: {click: {text: Download quote PDF}, as: quote}
      - hold: 1

  - card:
      component: studio/document-pdf
      slots: {document: quote, kicker: Quote PDF, title: "A real PDF, ready to share with your team."}
      params: {motion: zoom}
      duration: 4.5
    id: quote-pdf

